const body = $input.first().json.body;
const currentFloorPlanUrl = body.currentFloorPlanUrl;
const maskUrl = body.maskUrl || null;
const editPrompt = body.editPrompt;

// Fetch image and convert to base64
const imageResponse = await this.helpers.httpRequest({
  method: 'GET',
  url: currentFloorPlanUrl,
  encoding: 'arraybuffer'
});
const base64Image = Buffer.from(imageResponse).toString('base64');

// If mask is provided, we need to handle it differently
// For now, Gemini doesn't support masking, so we'll use text-only approach
const fullPrompt = editPrompt + " IMPORTANT: Maintain the same 3D isometric perspective and style. Keep the overall layout intact. Only make the specific change requested. Each bathroom should have exactly ONE toilet.";

// Return Gemini API format
return [{
  json: {
    contents: [{
      parts: [
        { text: fullPrompt },
        {
          inline_data: {
            mime_type: "image/png",
            data: base64Image
          }
        }
      ]
    }],
    generationConfig: {
      responseModalities: ["TEXT", "IMAGE"]
    }
  }
}];

const response = $input.first().json;

console.log('=== GEMINI EDIT RESULT ===');

const candidates = response.candidates;
if (!candidates || candidates.length === 0) {
  throw new Error('No candidates in response');
}

const parts = candidates[0].content.parts;
const imagePart = parts.find(p => p.inlineData);

if (!imagePart) {
  throw new Error('No image in response');
}

const base64Image = imagePart.inlineData.data;
const mimeType = imagePart.inlineData.mimeType || 'image/png';
const dataUrl = `data:${mimeType};base64,${base64Image}`;

console.log('✅ Floor plan edited');

return [{
  json: {
    imageUrl: dataUrl
  }
}];

